```java
import org.apache.spark.api.java.JavaPairRDD;
import org.apache.spark.api.java.JavaRDD;
import org.apache.spark.api.java.function.Function;
import org.apache.spark.api.java.function.PairFunction;
import scala.Tuple2;

import java.sql.Timestamp;
import java.util.HashMap;
import java.util.Map;

public class HitRateCalculator {

    public static void main(String[] args) {
        // Create SparkSession
        org.apache.spark.SparkConf conf = new org.apache.spark.SparkConf().setAppName("HitRateCalculator");
        org.apache.spark.api.java.JavaSparkContext sc = new org.apache.spark.api.java.JavaSparkContext(conf);
        org.apache.spark.api.java.JavaSparkSession session = org.apache.spark.api.java.JavaSparkSession.builder().appName("HitRateCalculator").config(sc.getConf()).getOrCreate();

        // Load onsite attributed data
        JavaRDD<String> onsiteAttributedData = session.read().textFile("path/to/onsite_attributed_data.csv").toJavaRDD();
        JavaRDD<Tuple2<String, Timestamp>> onsiteAttributedDataWithTimestamp = onsiteAttributedData.map(new Function<String, Tuple2<String, Timestamp>>() {
            @Override
            public Tuple2<String, Timestamp> call(String line) throws Exception {
                String[] fields = line.split(",");
                return new Tuple2<>(fields[0], new Timestamp(Long.parseLong(fields[1]) * 1000));
            }
        });

        // Load top frequent queries
        JavaRDD<String> topFrequentQueries = session.read().textFile("path/to/top_frequent_queries.txt").toJavaRDD();

        // Create a cache for queries
        Map<String, Timestamp> cache = new HashMap<>();

        // Process onsite attributed data
        JavaPairRDD<String, Integer> queryCounts = onsiteAttributedDataWithTimestamp.mapToPair(new PairFunction<Tuple2<String, Timestamp>, String, Integer>() {
            @Override
            public Tuple2<String, Integer> call(Tuple2<String, Timestamp> tuple) throws Exception {
                String query = tuple._1;
                Timestamp timestamp = tuple._2;

                // Check if query is in cache and if it's a cache miss
                if (cache.containsKey(query) && cache.get(query).before(timestamp.getTime() - (12 * 60 * 60 * 1000))) {
                    // Cache miss, send a request to retrieve the query and update the cache
                    System.out.println("Cache miss for query: " + query);
                    // TODO: Send a request to retrieve the query and update the cache
                    cache.put(query, timestamp);
                } else {
                    // Cache hit
                    System.out.println("Cache hit for query: " + query);
                }

                return new Tuple2<>(query, 1);
            }
        }).reduceByKey((a, b) -> a + b);

        // Save query counts to a file
        queryCounts.saveAsTextFile("path/to/query_counts.txt");

        // Calculate hit rate
        double hitRate = (double) queryCounts.filter(tuple -> topFrequentQueries.contains(tuple._1)).count() / queryCounts.count();
        System.out.println("Hit rate: " + hitRate);

        // Stop SparkContext
        sc.stop();
    }
}
```

