Create a `TooltipContext` to manage the state of the tooltip and a `useTooltip` hook to use the context in the component.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const value = { tooltip, setTooltip, closeTooltip };

  return (
    <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);

  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }

  return context;
};
```

Now, create the Tooltip component that uses the `useTooltip` hook to access the context and manage the tooltip state.

```jsx
import React, { useRef, useState } from 'react';
import { useTooltip } from './TooltipContext';

const Tooltip = ({ children, placement = 'bottom', delay = 0 }) => {
  const tooltipRef = useRef(null);
  const { tooltip, setTooltip, closeTooltip } = useTooltip();

  const [tooltipOpen, setTooltipOpen] = useState(false);

  const handleMouseEnter = () => {
    setTooltipOpen(true);
    setTooltip({ ref: tooltipRef.current, placement });
  };

  const handleMouseLeave = () => {
    if (delay) {
      setTimeout(closeTooltip, delay);
    } else {
      closeTooltip();
    }
  };

  return (
    <>
      {React.cloneElement(children, {
        onMouseEnter: handleMouseEnter,
        onMouseLeave: handleMouseLeave,
        ref: tooltipRef,
      })}
      {tooltipOpen && (
        <div
          className="tooltip"
          style={{ top: tooltip?.y, left: tooltip?.x }}
        >
          {tooltip?.content}
        </div>
      )}
    </>
  );
};

export default Tooltip;
```

