type resolver struct {
	ips map[string][]string
	mu  sync.Mutex
}

func (r *resolver) resolve(w dns.ResponseWriter, req *dns.Msg) {
	r.mu.Lock()
	defer r.mu.Unlock()

	m := new(dns.Msg)
	m.SetReply(req)

	for _, answer := range req.Question {
		ip := resolve(answer.Name, []net.IP{net.IPv4(8, 8, 8, 8), net.IPv4(1, 1, 1, 1)})
		if ip != nil {
			rr := new(dns.A)
			rr.Hdr = dns.RR_Header{Name: answer.Name, Rrtype: dns.TypeA, Class: req.Question[0].Class, Ttl: 300}
			rr.Rdata = ip
			m.Answer = append(m.Answer, rr)
			r.ips[answer.Name] = append(r.ips[answer.Name], ip.String())
		}
	}

	w.WriteMsg(m)
}

