                    stream.Write(sendBuffer, 0, sendBuffer.Length);

                    // Read the temperature response from the server.
                    stream.Read(receiveBuffer, 0, receiveBuffer.Length);
                    responseData = Encoding.ASCII.GetString(receiveBuffer, 0, bytesRead);

                    Console.WriteLine($"Temperature from server: {responseData}");

                    // Send the LOGOUT message.
                    sendBuffer = Encoding.ASCII.GetBytes("LOGOUT");
                    stream.Write(sendBuffer, 0, sendBuffer.Length);
                }

                // Close the connection.
                client.Close();
            }
            catch (Exception e)
            {
                Console.WriteLine("Error: " + e);
            }
        }
    }
