```swift
struct MSLAST {
    enum Node {
        case function(String, [Parameter])
        case variable(String)
        case type(String)
        case functionCall(String, [Expression])
        case binaryOperation(String, Expression, Expression)
        case unaryOperation(String, Expression)
        case assignment(String, Expression)
        case ifStatement(Expression, Statement, Statement?)
        case forLoop(String, Expression, Statement)
        case returnStatement(Expression?)
        case expression(Expression)

        enum Parameter {
            case input(String)
            case output(String)
            case uniform(String)
        }

        enum Expression {
            case identifier(String)
            case integer(Int)
            case float(Double)
            case boolean(Bool)
            case string(String)
        }

        enum Statement {
            case declaration(VariableDeclaration)
            case statement(Expression)
        }

        enum VariableDeclaration {
            case variable(String, Type)
            case uniform(String, Type)
        }

        enum Type {
            case float
            case int
            case bool
            case structType([String])
        }
    }

    let node: Node
}

struct VariableDeclaration {
    let name: String
    let type: MSLAST.Node.Type
}
```

