```bash
npm install xlsx lodash
```

Then, create a script (e.g., `compareExcelFiles.js`) to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareFiles(file1Path, file2Path, sheetName) {
  const workbook1 = XLSX.readFile(file1Path);
  const workbook2 = XLSX.readFile(file2Path);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const data1 = XLSX.utils.sheet_to_json(sheet1);
  const data2 = XLSX.utils.sheet_to_json(sheet2);

  const differences = _.differenceWith(data1, data2, _.isEqual);

  console.log('Discrepancies:', differences);
}

compareFiles('file1.xlsx', 'file2.xlsx', 'Sheet1');
```

Replace `'file1.xlsx'`, `'file2.xlsx'`, and `'Sheet1'` with the paths and sheet names of your Excel files.

Finally, run the script:

```bash
node compareExcelFiles.js
```

